CREATE DATABASE IF NOT EXISTS sentrax; USE sentrax;
CREATE TABLE IF NOT EXISTS app_user (id INT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(50) UNIQUE NOT NULL, password_hash VARCHAR(255) NOT NULL, role VARCHAR(20) DEFAULT 'ANALYST');
CREATE TABLE IF NOT EXISTS customer (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, home_city VARCHAR(80) NOT NULL, avg_amount DECIMAL(12,2) DEFAULT 0);
CREATE TABLE IF NOT EXISTS txn (id BIGINT AUTO_INCREMENT PRIMARY KEY, customer_id INT NOT NULL, amount DECIMAL(12,2) NOT NULL, merchant VARCHAR(100), location VARCHAR(80), device_id VARCHAR(80), txn_time DATETIME NOT NULL, risk_score INT DEFAULT 0, risk_level VARCHAR(15), reasons TEXT, FOREIGN KEY (customer_id) REFERENCES customer(id));
CREATE TABLE IF NOT EXISTS alert (id BIGINT AUTO_INCREMENT PRIMARY KEY, transaction_id BIGINT NOT NULL, status VARCHAR(15) DEFAULT 'OPEN', created_at DATETIME DEFAULT CURRENT_TIMESTAMP, resolved_at DATETIME NULL, FOREIGN KEY (transaction_id) REFERENCES txn(id));
